function suggest(prefix, limit) {
  let node = root;
  for (const ch of prefix) {
    node = node.children.get(ch);
    if (!node) return [];
  }
  const results = [];
  const stack = [[node, prefix]];
  while (stack.length > 0 && results.length < limit) {
    const [current, text] = stack.pop();
    if (current.end) results.push(text);
    const keys = [...current.children.keys()].sort().reverse();
    for (const ch of keys) stack.push([current.children.get(ch), text + ch]);
  }
  return results;
}

