const root = { children: new Map(), name: undefined };
const key = (text) => text.normalize("NFC").toLowerCase();

function add(name) {
  let node = root;
  for (const ch of key(name)) {
    if (!node.children.has(ch)) node.children.set(ch, { children: new Map(), name: undefined });
    node = node.children.get(ch);
  }
  node.name = name;
}

function lookup(query) {
  let node = root;
  for (const ch of key(query)) {
    node = node.children.get(ch);
    if (!node) return undefined;
  }
  return node.name;
}

